import {renderFormula,quantityHtml,proseHtml,mathHtml,notationTex} from './notation.js';
import {groups,modes,compute,fmt,nearOne,parseNumber} from './core.js';
import {svgChart,esc} from './plot.js';
import {exportArtifact,download} from './export.js';
const $=s=>document.querySelector(s);let currentGroup='inertia',currentMode='inertia',output=null,chartIndex=0,busy=false;const drafts=new Map(),plotOptions=new Map();
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200);}
function meta(){return {experiment:groups.find(g=>g[0]===currentGroup)[1]+' · '+modes[currentMode].title,author:$('#author').value.trim(),date:$('#date').value};}
function params(){return Object.fromEntries(modes[currentMode].params.map(p=>[p.id,$('#p-'+p.id).value]));}
function tables(){return Object.fromEntries(modes[currentMode].tables.map(t=>[t.id,$('#t-'+t.id).value]));}
function saveDraft(){if($('#tables').children.length)drafts.set(currentMode,{params:params(),tables:tables()});}
function removeDownload(){const a=$('#downloadLink');if(a){URL.revokeObjectURL(a.href);a.remove();}}
function resetResults(){removeDownload();output=null;chartIndex=0;plotOptions.clear();$('#metrics').innerHTML='';$('#chartTabs').innerHTML='';$('#resultsTable').innerHTML='';$('#chart').innerHTML='<div class="emptychart"><span>＋</span><strong>你的实验数据，将在这里成图</strong><p>输入数据后，计算结果与规范图表一同生成</p></div>';$('#resultState').textContent='等待数据';$('#resultState').className='status';document.querySelectorAll('[data-export]').forEach(b=>b.disabled=true);$('#error').hidden=true;$('#exportStatus').textContent='';}
function setGroup(group,save=true){if(save)saveDraft();currentGroup=group;const g=groups.find(x=>x[0]===group);if(!g)throw Error('未知实验。');$('#experimentNav').innerHTML=groups.map(x=>`<button data-group="${x[0]}" class="${group===x[0]?'active':''}" ${group===x[0]?'aria-current="true"':''}>${esc(x[1])}</button>`).join('');$('#experimentSelect').value=group;$('#modeSelect').innerHTML=g[2].map(id=>`<option value="${id}">${esc(modes[id].title)}</option>`).join('');setMode(g[2][0],false);}
function setMode(id,save=true){if(save)saveDraft();currentMode=id;const c=modes[id],saved=drafts.get(id);$('#modeSelect').value=id;$('#expTitle').textContent=groups.find(g=>g[0]===currentGroup)[1];$('#expSubtitle').innerHTML=proseHtml(c.subtitle);$('#inputHint').innerHTML=renderFormula(id);$('#parameters').innerHTML=c.params.map(p=>`<label for="p-${p.id}"><span class="paramcaption">${proseHtml(p.label)}${p.unit?' / '+mathHtml(notationTex(p.unit,true)):''}${p.optional?'（可选）':''}</span><input id="p-${p.id}" ${['xlabel','ylabel','transform','interpolate','quantity'].includes(p.id)?'type="text"':'type="text" inputmode="decimal"'} value="${esc(saved?.params?.[p.id]??p.value)}" ${p.value===''?'placeholder="请填写"':''}></label>`).join('');$('#tables').innerHTML=c.tables.map(t=>`<div class="dataBlock"><h3>${esc(t.label)}${t.optional&&!t.label.includes('可选')?'（可选）':''}</h3><p class="tableHint">${t.cols.map(quantityHtml).join('　｜　')}</p><textarea id="t-${t.id}" rows="6" aria-label="${esc(t.label)}" placeholder="填写本次实测数据，不含表头">${esc(saved?.tables?.[t.id]??'')}</textarea><p class="tableHint">每行一组，列间用空格、逗号或 Tab。可从 Excel 直接粘贴，不含表头。${id==='grating'?'角度可用 度:分 格式。':''}</p></div>`).join('');resetResults();$('#inputStatus').textContent='填写原始读数，保留原有小数位。姓名和日期留空时，图中保留填写空白。';}
function calculate(){if(busy)return;try{const candidate=compute(currentMode,params(),tables());output=candidate;chartIndex=0;plotOptions.clear();saveDraft();$('#error').hidden=true;renderOutput();$('#inputStatus').textContent='计算已更新，下载文件将使用这一次结果。';toast('计算与图表已更新');}catch(e){$('#error').textContent=e.message;$('#error').hidden=false;resetStale();}}
function resetStale(){removeDownload();document.querySelectorAll('[data-export]').forEach(b=>b.disabled=true);output=null;$('#resultState').textContent='需要检查输入';$('#resultState').className='status';$('#metrics').innerHTML='';$('#chartTabs').innerHTML='';$('#resultsTable').innerHTML='';$('#chart').innerHTML='<div class="emptychart"><span>＋</span><strong>请先检查输入数据</strong><p>修正后重新计算</p></div>';}
function renderOutput(){if(!output)return;$('#resultState').textContent='计算完成';$('#resultState').className='status ready';$('#metrics').innerHTML=output.metrics.slice(0,6).map(m=>`<div class="metric"><small>${proseHtml(m.label)}</small><strong>${m.label.includes('R²')||m.label.includes('系数 r')?nearOne(m.value):fmt(m.value,5)}</strong><span>${m.unit?mathHtml(notationTex(m.unit,true)):''}${m.u!==null?' · u='+fmt(m.u,3):''}</span></div>`).join('');$('#chartTabs').innerHTML=output.charts.map((c,i)=>`<button data-chart="${i}" class="${i===chartIndex?'active':''}">${esc(c.title)}</button>`).join('');$('#resultsTable').innerHTML=(output.warnings.length?'<div class="warn">'+output.warnings.map(esc).join('<br>')+'</div>':'')+output.processed.map(t=>`<details class="dataBlock"><summary>${esc(t.name)}（${t.rows.length}行）</summary><div class="tablewrap"><table><thead><tr>${t.headers.map(h=>`<th>${quantityHtml(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(r=>'<tr>'+r.map(v=>`<td>${typeof v==='number'?fmt(v,8):v===null?'未评估':esc(v)}</td>`).join('')+'</tr>').join('')}</tbody></table></div></details>`).join('');renderChart();document.querySelectorAll('[data-export]').forEach(b=>b.disabled=false);}
function renderChart(){if(!output)return;const c=output.charts[chartIndex],o=plotOptions.get(chartIndex)??{axes:{},special:false};try{$('#chart').innerHTML=svgChart(c,meta(),o).svg;$('#special').checked=o.special;$('#special').disabled=!c.fit;for(const name of ['xmin','xmax','xstep','ymin','ymax','ystep'])$('#'+name).value=o.axes[name]??'';document.querySelectorAll('[data-chart]').forEach(b=>b.classList.toggle('active',Number(b.dataset.chart)===chartIndex));}catch(e){toast(e.message);}}
$('#experimentSelect').innerHTML=groups.map(g=>`<option value="${g[0]}">${esc(g[1])}</option>`).join('');$('#experimentSelect').onchange=e=>setGroup(e.target.value);$('#experimentNav').onclick=e=>{const b=e.target.closest('[data-group]');if(b)setGroup(b.dataset.group);};$('#modeSelect').onchange=e=>setMode(e.target.value);$('#calculate').onclick=calculate;
$('#clear').onclick=()=>{modes[currentMode].tables.forEach(t=>$('#t-'+t.id).value='');drafts.delete(currentMode);resetResults();$('#inputStatus').textContent='本项数据已清空。';};
$('#tables').oninput=$('#parameters').oninput=()=>{removeDownload();saveDraft();if(output){document.querySelectorAll('[data-export]').forEach(b=>b.disabled=true);$('#resultState').textContent='输入已改变 · 请重算';$('#resultState').className='status';$('#inputStatus').textContent='数据已改变，旧结果暂存显示；点击“计算并作图”更新后再下载。';}};
$('#chartTabs').onclick=e=>{const b=e.target.closest('[data-chart]');if(b){chartIndex=Number(b.dataset.chart);renderChart();}};
$('#applyAxes').onclick=()=>{if(!output)return;const candidate={axes:Object.fromEntries(['xmin','xmax','xstep','ymin','ymax','ystep'].map(k=>[k,$('#'+k).value])),special:$('#special').checked};try{svgChart(output.charts[chartIndex],meta(),candidate);plotOptions.set(chartIndex,candidate);renderChart();toast('当前图的坐标已更新');}catch(e){toast(e.message);}};
for(const id of ['author','date'])$('#'+id).oninput=renderChart;
document.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{if(!output||busy)return;busy=true;document.querySelectorAll('[data-export]').forEach(x=>x.disabled=true);$('#exportStatus').textContent='正在生成文件，首次下载需要加载中文字体…';try{await exportArtifact(b.dataset.export,output,meta(),'',false,plotOptions,false);$('#exportStatus').textContent='文件已生成。图与源文件包可用于重新作图和复算。';}catch(e){$('#exportStatus').textContent='生成失败：'+e.message;toast('文件未生成，请重试');}finally{busy=false;document.querySelectorAll('[data-export]').forEach(x=>x.disabled=false);}});
$('#rulesContent').innerHTML='<p>依据《基础物理实验数据课2026秋季》及实验讲义的数据处理和作图要求。</p><ul><li>原始读数保留小数位；物理量与单位明确标注。</li><li>主刻度采用1、2、5的十进倍率；实测散点与模型、插值、外推分别说明。</li><li>自由截距最小二乘拟合，保留全部数据；参数标准误不代替仪器不确定度。</li><li>下载文件保留参数、原始数据、计算表、结果和图；源文件包可离线复算。</li></ul><p>数据在当前浏览器内计算，请下载文件保存。</p>';
setGroup('inertia',false);
// WebMCP: same validated action/state as the visible calculator.
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'calculate_physics_experiment',title:'计算物理实验数据',description:'验证实验参数和原始数据，更新网页的计算结果与图表。',inputSchema:{type:'object',properties:{mode:{type:'string',enum:Object.keys(modes)},params:{type:'object',additionalProperties:{type:'string'}},tables:{type:'object',additionalProperties:{type:'string'}}},required:['mode','params','tables'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||!modes[input.mode]||typeof input.params!=='object'||typeof input.tables!=='object')throw Error('输入格式错误。');const result=compute(input.mode,input.params,input.tables);const g=groups.find(g=>g[2].includes(input.mode));setGroup(g[0]);setMode(input.mode);modes[input.mode].params.forEach(p=>$('#p-'+p.id).value=input.params[p.id]??p.value);modes[input.mode].tables.forEach(t=>$('#t-'+t.id).value=input.tables[t.id]??'');output=result;saveDraft();renderOutput();return {mode:input.mode,metrics:result.metrics,graphs:result.charts.length,warnings:result.warnings};}},{signal:new AbortController().signal});}catch(e){console.info('WebMCP不可用',e);}}
// Embedded offline source package: explicitly restores this saved experiment only.
if(window.BOOTCONFIG){try{const c=window.BOOTCONFIG,g=groups.find(g=>g[2].includes(c.mode));if(g){setGroup(g[0]);setMode(c.mode);modes[c.mode].params.forEach(p=>$('#p-'+p.id).value=c.params[p.id]??p.value);modes[c.mode].tables.forEach(t=>$('#t-'+t.id).value=c.tables[t.id]??'');$('#author').value=c.meta?.author??'';$('#date').value=c.meta?.date??'';calculate();for(const [i,v] of c.plotOptions??[])plotOptions.set(i,v);renderChart();}}catch(e){toast('已保存数据恢复失败：'+e.message);}}
